SELECT MIN(date), MAX(date), COUNT(*) FROM store.daily_sales;
SELECT MIN(bill_ts), MAX(bill_ts), COUNT(*) FROM store.pos_lines;
SELECT MIN(audit_ts), MAX(audit_ts), COUNT(*) FROM store.shelf_audits;

SELECT MIN(date) AS min_d, MAX(date) AS max_d, COUNT(*) AS n FROM store.daily_sales;
SELECT MIN(bill_ts) AS min_b, MAX(bill_ts) AS max_b, COUNT(*) AS n FROM store.pos_lines;
SELECT MIN(audit_ts) AS min_a, MAX(audit_ts) AS max_a, COUNT(*) AS n FROM store.shelf_audits;

SELECT SUM(qty) AS total_units, COUNT(*) AS lines, COUNT(DISTINCT bill_id) AS bills
FROM store.pos_lines
WHERE sku_scanned='ATTA-WW-5KG' AND bill_ts >= '2026-06-01' AND bill_ts < '2026-07-01';

SELECT SUM(units_sold) AS total_units, SUM(revenue_inr) AS total_rev
FROM store.daily_sales
WHERE sku='ATTA-WW-5KG' AND date >= '2026-06-01' AND date <= '2026-06-30';

SELECT date, book_on_hand_close FROM store.inventory_book
WHERE sku='ATTA-WW-5KG' AND date >= '2026-06-01' AND date <= '2026-06-30'
ORDER BY date;

SELECT count_ts, book_before, counted, adjustment, trigger
FROM store.stock_counts WHERE sku='ATTA-WW-5KG' ORDER BY count_ts;
SELECT record_date, write_off_units, write_off_reason FROM store.write_offs WHERE sku='ATTA-WW-5KG' ORDER BY record_date;

SELECT count_ts, book_before, counted, adjustment, trigger
FROM store.stock_counts WHERE sku='ATTA-WW-5KG' ORDER BY count_ts;
SELECT date, units, reason FROM store.write_offs WHERE sku='ATTA-WW-5KG' ORDER BY date;
